import { useState } from 'react';
import { fmt } from '../utils/format';
import { STORES } from '../utils/config';

const PRODUCTS = [
  {code:'BDLN201', name:'麗容酵素入浴劑 880g',           cost:186, brand:'LEON',
   qW:5,  qM:19, qTS:0, qTW:0, qTSL:0, qE:240, u:1},
  {code:'BDLN203', name:'麗容酵素入浴劑 880g 3入組',     cost:558, brand:'LEON',
   qW:3,  qM:0,  qTS:21,qTW:0, qTSL:0, qE:0,   u:3},
  {code:'BDLN103', name:'麗容酵素入浴劑 600g 3入組',     cost:480, brand:'LEON',
   qW:0,  qM:0,  qTS:4, qTW:0, qTSL:0, qE:0,   u:3},
  {code:'BDLN101', name:'麗容酵素入浴劑 600g',           cost:160, brand:'LEON',
   qW:0,  qM:0,  qTS:0, qTW:0, qTSL:0, qE:936, u:1},
  {code:'BDTL101', name:'多樂 B5 多效保濕修護霜',        cost:150, brand:'TOOLA',
   qW:8,  qM:0,  qTS:1, qTW:0, qTSL:0, qE:24,  u:1},
  {code:'BDTL201', name:'多樂 嬰幼兒洗沐泡泡露－英國梨', cost:81,  brand:'TOOLA',
   qW:12, qM:0,  qTS:0, qTW:0, qTSL:0, qE:53,  u:1},
  {code:'BDTL301', name:'多樂慕絲－英國梨&麝香',         cost:62,  brand:'TOOLA',
   qW:10, qM:0,  qTS:1, qTW:0, qTSL:0, qE:95,  u:1},
  {code:'BDTL401', name:'多樂慕絲－純淨無香',            cost:62,  brand:'TOOLA',
   qW:8,  qM:0,  qTS:0, qTW:0, qTSL:0, qE:65,  u:1},
  {code:'BDTL0029',name:'多樂 嬰幼兒全系列體驗組',       cost:293, brand:'TOOLA',
   qW:6,  qM:0,  qTS:0, qTW:0, qTSL:0, qE:0,   u:1},
];

// 平台欄位定義
const PLATFORMS = [
  { id:'ALL',            label:'全部',     keys:['qW','qM','qTS','qTW','qTSL','qE'],  color:'var(--text)' },
  { id:'TOOLA_SHOPLINE', label:'TOOLA 官網', keys:['qW'],   color:'#00f5ff' },
  { id:'MOMO',           label:'momo',     keys:['qM'],   color:'#ff006e' },
  { id:'TOOLA_SHOPEE',   label:'TOOLA 蝦皮', keys:['qTS'],  color:'#00f5ff' },
  { id:'TAKUYA_SHOPEE',  label:'拓屋 蝦皮',  keys:['qTW'],  color:'#f5c400' },
  { id:'TAKUYA_SHOPLINE',label:'拓屋 官網',  keys:['qTSL'], color:'#f5c400' },
  { id:'ERP',            label:'經銷',     keys:['qE'],   color:'#00ff9f' },
];

const KEY_LABEL = {
  qW:'官網', qM:'momo', qTS:'TOOLA蝦皮', qTW:'拓屋蝦皮', qTSL:'拓屋官網', qE:'經銷'
};
const KEY_COLOR = {
  qW:'var(--cyan)', qM:'var(--pink)', qTS:'var(--cyan)', qTW:'var(--yellow)', qTSL:'var(--yellow)', qE:'var(--green)'
};

export default function SalesPage() {
  const [platFilter, setPlatFilter] = useState('ALL');
  const activePlat = PLATFORMS.find(p => p.id === platFilter) || PLATFORMS[0];
  const activeKeys = activePlat.keys;

  const rows = PRODUCTS.map(p => {
    const qByKey = { qW:p.qW, qM:p.qM, qTS:p.qTS, qTW:p.qTW, qTSL:p.qTSL, qE:p.qE };
    const filteredQty = activeKeys.reduce((s, k) => s + (qByKey[k]||0), 0);
    const totalQty    = Object.values(qByKey).reduce((s, v) => s + v, 0);
    const units       = filteredQty * p.u;
    const rev         = (p.qW*(p.cost/0.45)) + (p.qM*(p.cost/0.45)) +
                        (p.qTS*(p.cost/0.45)) + (p.qTW*(p.cost/0.45)) +
                        (p.qTSL*(p.cost/0.45)) + (p.qE*(p.cost/0.35)*1.05);
    const filteredRev = activeKeys.includes('qE')
      ? (activeKeys.includes('qW') ? rev : p.qE*(p.cost/0.35)*1.05)
      : activeKeys.reduce((s, k) => s + (qByKey[k]||0)*(p.cost/0.45), 0);
    const costTotal   = filteredQty * p.cost;
    return { ...p, qByKey, filteredQty, units, filteredRev, costTotal, gross: filteredRev - costTotal };
  }).filter(p => p.filteredQty > 0 || platFilter === 'ALL');

  const T = rows.reduce((a, r) => ({
    qty:   a.qty   + r.filteredQty,
    units: a.units + r.units,
    rev:   a.rev   + r.filteredRev,
    cost:  a.cost  + r.costTotal,
    gross: a.gross + r.gross,
  }), { qty:0, units:0, rev:0, cost:0, gross:0 });

  return (
    <div>
      {/* 平台篩選 */}
      <div style={{ display:'flex', gap:6, marginBottom:16, flexWrap:'wrap' }}>
        {PLATFORMS.map(p => (
          <button key={p.id}
            className={`btn btn-sm ${platFilter===p.id ? 'btn-primary' : 'btn-ghost'}`}
            style={platFilter===p.id ? { borderColor:p.color, color:p.color, background:`${p.color}15`, boxShadow:`0 0 8px ${p.color}30` } : {}}
            onClick={() => setPlatFilter(p.id)}>
            {p.label}
          </button>
        ))}
      </div>

      <div className="card">
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>代號</th>
                <th>品名</th>
                <th>品牌</th>
                <th style={{ textAlign:'right' }}>含稅成本</th>
                {platFilter === 'ALL'
                  ? Object.keys(KEY_LABEL).map(k => (
                      <th key={k} style={{ textAlign:'right', background:`${KEY_COLOR[k]}15`, color:KEY_COLOR[k] }}>{KEY_LABEL[k]}</th>
                    ))
                  : activeKeys.map(k => (
                      <th key={k} style={{ textAlign:'right', background:`${activePlat.color}15`, color:activePlat.color }}>{KEY_LABEL[k]}</th>
                    ))
                }
                <th style={{ textAlign:'right', background:'rgba(180,79,255,0.1)', color:'var(--purple)' }}>套組合計</th>
                <th style={{ textAlign:'right', background:'rgba(245,196,0,0.1)', color:'var(--yellow)' }}>單品換算</th>
                <th style={{ textAlign:'right', background:'rgba(0,245,255,0.08)', color:'var(--cyan)' }}>銷售金額</th>
                <th style={{ textAlign:'right', background:'rgba(255,0,110,0.08)', color:'var(--pink)' }}>銷貨成本</th>
                <th style={{ textAlign:'right' }}>毛利</th>
              </tr>
            </thead>
            <tbody>
              {rows.map(p => {
                const brandColors = { TOOLA:'var(--cyan)', LEON:'var(--purple)', TAKUYA:'var(--yellow)' };
                const bColor = brandColors[p.brand] || 'var(--muted)';
                return (
                  <tr key={p.code}>
                    <td className="td-mono" style={{ color:'var(--cyan)', fontWeight:700, fontSize:13 }}>{p.code}</td>
                    <td style={{ maxWidth:160, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{p.name}</td>
                    <td><span style={{ fontSize:12, color:bColor, background:`${bColor}15`, padding:'2px 6px', borderRadius:3, border:`1px solid ${bColor}30` }}>{p.brand}</span></td>
                    <td className="td-right td-mono" style={{ color:'var(--muted)' }}>{fmt.currency(p.cost)}</td>
                    {platFilter === 'ALL'
                      ? Object.keys(KEY_LABEL).map(k => (
                          <td key={k} className="td-right td-mono" style={{ background:`${KEY_COLOR[k]}08`, color: p.qByKey[k] > 0 ? KEY_COLOR[k] : 'rgba(255,255,255,0.15)', fontWeight: p.qByKey[k] > 0 ? 600 : 400 }}>
                            {p.qByKey[k] > 0 ? p.qByKey[k] : '–'}
                          </td>
                        ))
                      : activeKeys.map(k => (
                          <td key={k} className="td-right td-mono" style={{ background:`${activePlat.color}08`, color: p.qByKey[k] > 0 ? activePlat.color : 'rgba(255,255,255,0.15)', fontWeight: p.qByKey[k] > 0 ? 700 : 400 }}>
                            {p.qByKey[k] > 0 ? p.qByKey[k] : '–'}
                          </td>
                        ))
                    }
                    <td className="td-right td-mono" style={{ color:'var(--purple)', fontWeight:700 }}>{p.filteredQty}</td>
                    <td className="td-right td-mono" style={{ color:'var(--yellow)', fontWeight:700 }}>
                      {p.units}{p.u > 1 && <span style={{ fontSize:11, opacity:0.5, marginLeft:3 }}>×{p.u}</span>}
                    </td>
                    <td className="td-right td-mono" style={{ color:'var(--cyan)', fontWeight:600 }}>{fmt.currency(p.filteredRev)}</td>
                    <td className="td-right td-mono" style={{ color:'var(--pink)' }}>{fmt.currency(p.costTotal)}</td>
                    <td className="td-right td-mono" style={{ color: p.gross>=0?'var(--green)':'var(--red)', fontWeight:600 }}>{fmt.currency(p.gross)}</td>
                  </tr>
                );
              })}
            </tbody>
            <tfoot>
              <tr style={{ background:'rgba(0,245,255,0.06)', borderTop:'2px solid var(--cyan)' }}>
                <td colSpan={4} style={{ fontFamily:'var(--title)', fontWeight:700, fontSize:15, color:'var(--cyan)', padding:'11px 14px', letterSpacing:2 }}>合　計</td>
                <td colSpan={platFilter==='ALL' ? 6 : activeKeys.length} style={{ background:'rgba(0,245,255,0.04)' }}/>
                <td className="td-right td-mono" style={{ color:'var(--purple)', fontWeight:700 }}>{T.qty}</td>
                <td className="td-right td-mono" style={{ color:'var(--yellow)', fontWeight:700 }}>{T.units}</td>
                <td className="td-right td-mono" style={{ color:'var(--cyan)', fontWeight:700 }}>{fmt.currency(T.rev)}</td>
                <td className="td-right td-mono" style={{ color:'var(--pink)', fontWeight:700 }}>{fmt.currency(T.cost)}</td>
                <td className="td-right td-mono" style={{ color:'var(--green)', fontWeight:700 }}>{fmt.currency(T.gross)}</td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    </div>
  );
}